import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line != null) {StringTokenizer st = new StringTokenizer(line);if (st.hasMoreTokens()) {int n = Integer.parseInt(st.nextToken());out.println(n);}}out.flush();out.close();}}